/bin/bash -lc "cat > /tmp/create_lab_dns.py <<'PY'
from pathlib import Path
import re
root=Path('.')
zones=['.','com','net','edu','it','example.com','company.com','service.com','lab.net','tools.net','university.edu','campus.edu','unibo.it','comune.it','regione.it','shop.example.com','blog.example.com','dept.company.com','intranet.company.com','api.service.com','research.lab.net','ai.research.lab.net','data.research.lab.net','dev.lab.net','ci.tools.net','vpn.university.edu','courses.university.edu','portal.campus.edu','studenti.unibo.it','servizi.comune.it','dati.regione.it','org','io','gov','info','foundation.org','project.org','startup.io','platform.io','ministero.gov','news.info','archive.foundation.org','docs.project.org','api.startup.io','status.platform.io','open.ministero.gov','servizi.ministero.gov','local.news.info','media.news.info']
ips={i:re.search(r\"inet (\\d+\\.\\d+\\.\\d+\\.\\d+)/\",Path(f'pc{i}.startup').read_text()).group(1) for i in range(1,61)}
byzone={z:i for i,z in enumerate(zones,1)}
def fq(z): return z+'.' if z"'!='"'.' else '.'
def ns(z): return 'ns.root.' if z=='.' else 'ns.'+z+'.'
children={z:[] for z in zones}
for z in zones[1:]:
    parent=z.split('.',1)[1] if '.' in z else '.'
    children[parent].append(z)
mail={'company.com','university.edu','dept.company.com','servizi.ministero.gov'}
for z,i in byzone.items():
    d=Path(f'pc{i}/etc/bind'); d.mkdir(parents=True,exist_ok=True)
    (d/'named.conf.lab').write_text('''options {
    directory \"/tmp\";
    listen-on port 53 { any; };
    listen-on-v6 { none; };
    recursion no;
    allow-query { any; };
    dnssec-validation no;
    pid-file \"/run/named-lab.pid\";
};
zone \"%s\" { type primary; file \"/etc/bind/db.lab\"; };
''' % z)
    lines=['"'$TTL 3600'"',f'"'$ORIGIN {fq(z)}'"',f'@ IN SOA {ns(z)} hostmaster.{\"root.\" if z==\".\" else fq(z)} (', '    2026110301 3600 900 604800 3600 )',f'@ IN NS {ns(z)}',f'@ IN A {ips[i]}',f'{ns(z)} IN A {ips[i]}']
    if z in mail: lines += [f'@ IN MX 10 mail.{z}.',f'mail.{z}. IN A {ips[i]}']
    for c in children[z]: lines += [f'{fq(c)} IN NS {ns(c)}',f'{ns(c)} IN A {ips[byzone[c]]}']
    (d/'db.lab').write_text('\\n'.join(lines)+'\\n')
d=Path('pc50/etc/bind'); d.mkdir(parents=True,exist_ok=True)
(d/'named.conf.lab').write_text('''options {
    directory \"/tmp\";
    listen-on port 53 { any; };
    listen-on-v6 { none; };
    recursion yes;
    allow-query { any; };
    allow-recursion { any; };
    allow-query-cache { any; };
    dnssec-validation no;
    empty-zones-enable no;
    pid-file \"/run/named-lab.pid\";
};
zone \".\" { type hint; file \"/etc/bind/db.lab-root\"; };
''')
(d/'db.lab-root').write_text(f'. 3600 IN NS ns.root.\\nns.root. 3600 IN A {ips[1]}\\n')
for i in range(1,61):
    p=Path(f'pc{i}.startup')
    extra=f'\\n# DNS lab: all PC resolvers use pc50.\\nprintf \"nameserver {ips[50]}\\\\noptions timeout:2 attempts:3\\\\n\" > /etc/resolv.conf\\n'
    if i<=50: extra+='\\n# Start the lab DNS server after configuring the existing network.\\n/usr/sbin/named -4 -u root -c /etc/bind/named.conf.lab\\n'
    p.write_text(p.read_text()+extra)
print('zones',len(zones),'delegations',sum(map(len,children.values())),'resolver',ips[50])
PY
python3 /tmp/create_lab_dns.py
cat pc1/etc/bind/db.lab
cat pc18/etc/bind/db.lab"

